  1→// 通用 Android 性能分析平台 · P0 领域模型地基
  2→//
  3→// 依据:
  4→//   - docs/analysis-framework-design.md §5 (Run = raw + core + detail) / §6 (分层 + skill 架构)
  5→//   - docs/performance-platform-requirements-v2.md §2 (领域模型) / §8 (insights) / §11 (命名迁移)
  6→//
  7→// 命名约定 (硬约束):
  8→//   - 无 Maple 关键字; pdata/.pdata 统一为 UnityProfilerData, 源 id = 'unity_profiler'。
  9→//   - core 用"指标袋 metrics[]"承载跨源可比指标, 禁止 il2cppBasePct 这类用例耦合的硬编码列。
 10→//   - detail 为 schemaless 原样留档, 新维度进 detail, 不撑爆 core。
 11→
 12→// ============================================================
 13→// 源标识
 14→// ============================================================
 15→
 16→/** 数据源 id。已知三源 + 可扩展 (新增源遵循"1 Provider + 1 单源 skill")。 */
 17→export type SourceId = 'unity_profiler' | 'simpleperf' | 'perfetto' | (string & {});
 18→
 19→/** 已落地的三源 (用于遍历 / 校验)。 */
 20→export const KNOWN_SOURCE_IDS = ['unity_profiler', 'simpleperf', 'perfetto'] as const;
 21→
 22→// ============================================================
 23→// core —— 归一化指标 (统一词汇表)
 24→// ============================================================
 25→
 26→/** 帧口径: 不同源各一条, 禁止默认直比 (Choreographer ≠ PlayerLoop)。 */
 27→export type FrameDefinition = 'playerloop' | 'choreographer' | 'frametimeline' | (string & {});
 28→
 29→export type MetricUnit = 'ms' | '%' | 'pp' | 'mhz' | 'count' | 'mb' | 'bytes' | (string & {});
 30→
 31→export type Confidence = 'high' | 'medium' | 'low';
 32→
 33→/**
 34→ * 指标袋的一行。加指标 = 多一行, 不改表结构。
 35→ * key 采用统一命名空间, 例: 'cpu.lib.libil2cpp.pct' / 'frame.p95Ms' / 'system.cpuFreqAvgMhz'。
 36→ */
 37→export interface Metric {
 38→  key: string;
 39→  value: number;
 40→  unit: MetricUnit;
 41→  source: SourceId;
 42→  confidence?: Confidence;
 43→}
 44→
 45→/** 帧分布 (每源一条, 显式标注口径)。 */
 46→export interface FrameStat {
 47→  source: SourceId;
 48→  frameDefinition: FrameDefinition;
 49→  p50Ms: number;
 50→  p95Ms: number;
 51→  p99Ms: number;
 52→  fps: number;
 53→  /** 慢帧占比 (0-1 或 %, 由 source 决定, 文案需注明)。 */
 54→  slowFrameRate: number;
 55→}
 56→
 57→/** 线程调度状态 (主要来自 perfetto)。 */
 58→export interface ThreadStat {
 59→  source: SourceId;
 60→  name: string;
 61→  runningPct: number;
 62→  runnablePct: number;
 63→  sleepingPct: number;
 64→}
 65→
 66→/** 系统级状态 (频率 / 降频 / GPU / binder / 内存)。字段可缺失 → 降级。 */
 67→export interface SystemStat {
 68→  cpuFreqAvgMhz?: number;
 69→  cpuThrottled?: boolean;
 70→  thermalC?: number;
 71→  gpuBusyPct?: number;
 72→  binder?: { count: number; avgMs: number };
 73→  pssMb?: number;
 74→}
 75→
 76→/** 跨源可信度: 帧偏差超阈值即告警。 */
 77→export interface ProfileConfidence {
 78→  perFrameAlignmentOk: boolean;
 79→  notes: string[];
 80→}
 81→
 82→/** 当前归一化逻辑版本。core 由 raw 重算时据此判断是否需要重解析。 */
 83→export const PERF_PROFILE_SCHEMA_VERSION = 1;
 84→
 85→/** core —— 物化入库的归一化视图, 服务于单次展示 / 列表 / 趋势。 */
 86→export interface PerfProfileCore {
 87→  schemaVersion: number;
 88→  metrics: Metric[];
 89→  frame: FrameStat[];
 90→  threads: ThreadStat[];
 91→  system: SystemStat;
 92→  confidence: ProfileConfidence;
 93→}
 94→
 95→// ============================================================
 96→// CallTree —— 三源共享的"以已知根为起点的每线程调用树" (contract §1.5)
 97→//
 98→// 决策 8: 三源都产"以已知根为起点的每线程调用树", 统一结构, 放 detail.<source>.callTrees。
 99→// 这棵树同时支撑单源热点(self 最高节点) / anchor(选定节点 totalPct) / 对比差分(同名节点配对做减法)。
100→// 无树的新源 (Thermal/PMU 等) 不产即可, 不破坏可插拔。
101→// ============================================================
102→
103→/** 节点层次标签 (主要 simpleperf 用; unity/perfetto 可不填)。 */
104→export type CallTreeLayer = 'business' | 'engine' | 'runtime' | 'noise' | (string & {});
105→
106→/** 统一调用树节点。三源 detail 都放一份, 字段名一致 (便于对比层按名配对)。 */
107→export interface CallTreeNode {
108→  name: string;
109→  /** 自身耗时 (不含子树)。 */
110→  selfMs?: number;
111→  selfPct?: number;
112→  /** 子树总耗时。 */
113→  totalMs?: number;
114→  totalPct?: number;
115→  /** 层次标签 (simpleperf 用; 业务/引擎/运行时/噪音)。 */
116→  layer?: CallTreeLayer;
117→  children: CallTreeNode[];
118→}
119→
120→/** 一棵以某根 (PlayerLoop / 线程入口) 为起点的调用树。挂在 detail.<source>.callTrees[]。 */
121→export interface CallTree {
122→  /** 树所属线程名。 */
123→  thread: string;
124→  /** 可选: 这棵树的取样来源 (如 'worstFrame#123' / 'medianFrame' / 'thread-total')。 */
125→  label?: string;
126→  root: CallTreeNode;
127→}
128→
129→// ============================================================
130→// detail —— schemaless 各源富数据 (不归一化)
131→// ============================================================
132→
